using UnityEngine;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using FPS; // EnemyHealth
namespace FPS
{

    // Système de dash directionnel
    // Permet au joueur de dasher dans la direction de la caméra et de tuer les ennemis sur son passage
    public class DashSystem : MonoBehaviour
    {
        [Header("Dash Settings")]
        [Tooltip("Vitesse du dash")]
        [SerializeField] private float dashSpeed = 25f;

        [Tooltip("Durée du dash en secondes")]
        [SerializeField] private float dashDuration = 0.4f;

        [Tooltip("Courbe de vitesse du dash (X = temps normalisé 0-1, Y = multiplicateur de vitesse)")]
        [SerializeField] private AnimationCurve dashSpeedCurve = AnimationCurve.EaseInOut(0f, 1f, 1f, 0.3f);

        [Header("Dash Charge Settings")]
        [Tooltip("Activer la régénération automatique du dash (désactiver pour forcer le kill d'ennemis)")]
        [SerializeField] private bool autoRegenerate = false;

        [Tooltip("Cooldown entre chaque dash en secondes (uniquement si autoRegenerate est activé)")]
        [SerializeField] private float dashCooldown = 1.5f;

        [Tooltip("Nombre d'ennemis spéciaux à tuer pour remplir complètement la barre de dash")]
        [SerializeField] private int enemiesRequiredForFullCharge = 3;

        [Tooltip("Charge de dash actuelle (0 à 1)")]
        [SerializeField] private float currentDashCharge = 1f;

        [Tooltip("Rayon de détection des ennemis pendant le dash")]
        [SerializeField] private float dashHitRadius = 1.0f;

        [Tooltip("Dégâts infligés aux ennemis touchés")]
        [SerializeField] private float dashDamage = 9999f;

        [Tooltip("LayerMask pour détecter les ennemis")]
        [SerializeField] private LayerMask enemyMask = ~0;

        [Header("Collision Settings")]
        [Tooltip("Angle maximum (en degrés) entre la direction du dash et la surface pour continuer le dash. Au-delà, le dash s'arrête.")]
        [SerializeField] private float maxCollisionAngle = 45f;

        [Tooltip("LayerMask pour les obstacles qui peuvent arrêter le dash")]
        [SerializeField] private LayerMask obstacleMask = ~0;

        [Tooltip("Distance de détection des obstacles devant le joueur")]
        [SerializeField] private float obstacleCheckDistance = 0.5f;

        [Header("FOV Settings")]
        [Tooltip("FOV pendant le dash")]
        [SerializeField] private float dashFOV = 90f;

        [Tooltip("Vitesse de transition du FOV")]
        [SerializeField] private float fovTransitionSpeed = 15f;

        [Header("Momentum Settings")]
        [Tooltip("Conserver l'énergie cinétique à la sortie du dash")]
        [SerializeField] private bool conserveMomentum = true;

        [Tooltip("Pourcentage du momentum du dash à conserver (0 à 1)")]
        [SerializeField] private float momentumRetention = 0.8f;

        [Header("References")]
        [SerializeField] private FPSPlayerController playerController;
        [SerializeField] private FPSMovement fpsMovement;
        [SerializeField] private Transform cameraTransform;
        [SerializeField] private SoundPlayer sound;

        private Camera playerCamera;
        private float defaultFOV;
        private float targetFOV;

        public bool isDashing = false;
        private float dashTimer = 0f;
        private float cooldownTimer = 0f;

        private CharacterController characterController;

        private static System.Collections.Generic.HashSet<GameObject> enemiesKilledByDash = new System.Collections.Generic.HashSet<GameObject>();

        // Runtime
        private Vector3 directionalDashDir;
        private Vector3 lastDashPosition;
        private readonly HashSet<GameObject> _hitThisDash = new HashSet<GameObject>();
        private static readonly RaycastHit[] _hitBuffer = new RaycastHit[32];

        private void Start()
        {
            if (playerController == null)
            {
                playerController = GetComponent<FPSPlayerController>();
                if (playerController == null)
                {
                    return;
                }
            }

            if (fpsMovement == null)
            {
                fpsMovement = GetComponent<FPSMovement>();
            }

            if (cameraTransform == null)
            {
                cameraTransform = playerController.CameraTransform;
                if (cameraTransform == null)
                {
                    return;
                }
            }

            if (cameraTransform != null)
            {
                playerCamera = cameraTransform.GetComponent<Camera>();
                if (playerCamera != null)
                {
                    defaultFOV = playerCamera.fieldOfView;
                    targetFOV = defaultFOV;
                }
            }

            characterController = playerController.Controller;
        }

        private void Update()
        {
            // Mise à jour du cooldown
            if (autoRegenerate && cooldownTimer < dashCooldown)
            {
                cooldownTimer += Time.deltaTime;

                // Régénération automatique de la charge
                if (cooldownTimer >= dashCooldown && currentDashCharge < 1f)
                {
                    currentDashCharge = 1f;
                }
            }

            // Empêcher le dash pendant un stun
            var stunComp = GetComponent<PlayerStunAutoFire>();
            bool isStunned = stunComp != null && stunComp.IsStunned;

            // Gestion du dash
            if (isDashing)
            {
                HandleDash();
            }
            else
            {
                bool hasCharge = currentDashCharge >= 1f;
                bool cooldownReady = autoRegenerate ? (cooldownTimer >= dashCooldown) : true;

                if (!isStunned && Input.GetMouseButtonDown(1) && hasCharge && cooldownReady)
                {
                    StartDirectionalDash();
                }
            }

            // Gestion du FOV
            UpdateFOV();
        }

        private void FixedUpdate()
        {
            if (!isDashing || characterController == null) return;

            // Vérifier les obstacles devant le joueur
            if (CheckObstacleCollision())
            {
                EndDash();
                return;
            }

            float dashProgress = Mathf.Clamp01(dashTimer / dashDuration);

            // Évaluer la courbe pour obtenir le multiplicateur de vitesse
            float speedMultiplier = dashSpeedCurve.Evaluate(dashProgress);

            // Mouvement en ligne droite selon la direction de dash avec la courbe appliquée
            Vector3 dashMovement = directionalDashDir * (dashSpeed * speedMultiplier * Time.fixedDeltaTime);

            Vector3 currentPos = transform.position;
            Vector3 nextPos = currentPos + dashMovement;
            Vector3 seg = nextPos - lastDashPosition;
            float segLen = seg.magnitude;
            if (segLen > 0.0001f)
            {
                int hits = Physics.SphereCastNonAlloc(
                    lastDashPosition,
                    dashHitRadius,
                    seg.normalized,
                    _hitBuffer,
                    segLen,
                    enemyMask,
                    QueryTriggerInteraction.Ignore
                );
                for (int i = 0; i < hits; i++)
                {
                    var h = _hitBuffer[i];
                    if (h.collider == null) continue;
                    var enemyHealth = h.collider.GetComponentInParent<EnemyHealth>() ?? h.collider.GetComponent<EnemyHealth>();
                    if (enemyHealth == null) continue;

                    var enemyRoot = enemyHealth.transform.root.gameObject;
                    if (_hitThisDash.Contains(enemyRoot)) continue;
                    _hitThisDash.Add(enemyRoot);

                    // Si c'est un ennemi électrique -> stun le joueur (auto-fire)
                    var electric = h.collider.GetComponentInParent<Ennemies.Effect.ElectricEnnemis>() ?? h.collider.GetComponent<Ennemies.Effect.ElectricEnnemis>();
                    if (electric != null)
                    {
                        var playerStun = GetComponent<PlayerStunAutoFire>();
                        if (playerStun == null) playerStun = gameObject.AddComponent<PlayerStunAutoFire>();
                        if (electric.OverrideAutoFireInterval)
                            playerStun.ApplyStun(electric.StunDuration, electric.StunAutoFireInterval);
                        else
                            playerStun.ApplyStun(electric.StunDuration);

                        // Arrêter le dash immédiatement à cause du stun électrique
                        EndDash();
                        return;
                    }

                    // Marquer comme kill par dash si le coup sera létal
                    bool willDie = enemyHealth.CurrentHealth <= dashDamage;
                    if (willDie)
                    {
                        enemiesKilledByDash.Add(enemyRoot);
                        StartCoroutine(CleanupEnemyTracking(enemyRoot));

                        // Désactiver immédiatement les collisions pour permettre le dash à travers
                        DisableEnemyCollisions(enemyRoot);
                    }

                    // Appliquer dégâts
                    // enemyHealth.TakeDamage(dashDamage, "Dash");
                    enemyHealth.TakeDamage(new DamageInfo(dashDamage, "Dash", DamageType.Dash));
                }
            }

            lastDashPosition = nextPos;
            characterController.Move(dashMovement);
            Debug.DrawRay(transform.position, directionalDashDir * 3f, Color.cyan, 0.05f);
        }

        private void StartDirectionalDash()
        {
            Vector3 fwd;
            if (playerCamera != null)
            {
                Ray aimRay = playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
                fwd = aimRay.direction;
            }
            else if (cameraTransform != null)
            {
                fwd = cameraTransform.forward;
            }
            else
            {
                fwd = transform.forward;
            }

            if(sound != null)
            {
                sound.PlayOneShot("Dash");
            }

            directionalDashDir = fwd.normalized;

            currentDashCharge = 0f;

            // Mettre la vitesse de mouvement au maximum
            if (fpsMovement != null)
            {
                fpsMovement.SetSpeedToMax();
            }

            // Init timers/état
            isDashing = true;
            dashTimer = 0f;
            targetFOV = dashFOV;
            lastDashPosition = transform.position;
            _hitThisDash.Clear();
        }

        private void HandleDash()
        {
            dashTimer += Time.deltaTime;

            if (dashTimer >= dashDuration)
            {
                EndDash();
            }
        }

        // Vérifie si le dash doit être arrêté par une collision avec un obstacle à mauvais angle
        private bool CheckObstacleCollision()
        {
            // Raycast dans la direction du dash pour détecter les obstacles
            RaycastHit hit;
            float checkDistance = obstacleCheckDistance;

            // SphereCast pour détecter les obstacles devant le joueur avec un rayon similaire au dashHitRadius
            if (Physics.SphereCast(
                transform.position,
                dashHitRadius * 0.8f, // Légèrement plus petit pour éviter les faux positifs
                directionalDashDir,
                out hit,
                checkDistance,
                obstacleMask,
                QueryTriggerInteraction.Ignore))
            {
                // Ignorer si c'est un ennemi (ils sont gérés séparément)
                var enemyHealth = hit.collider.GetComponentInParent<EnemyHealth>() ?? hit.collider.GetComponent<EnemyHealth>();
                if (enemyHealth != null)
                {
                    return false; // Ne pas arrêter le dash pour les ennemis
                }

                // Calculer l'angle entre la direction du dash et la normale de la surface
                float angle = Vector3.Angle(directionalDashDir, -hit.normal);

                // Debug visuel
                Debug.DrawRay(hit.point, hit.normal * 2f, Color.red, 0.1f);
                Debug.DrawRay(hit.point, directionalDashDir * 2f, Color.yellow, 0.1f);

                // Si l'angle est trop abrupt (surface trop perpendiculaire à la direction du dash)
                if (angle > maxCollisionAngle)
                {
                    Debug.Log($"[DashSystem] Dash arrêté par collision ! Angle: {angle:F1}° (max: {maxCollisionAngle}°)");
                    return true; // Arrêter le dash
                }
            }

            return false; // Continuer le dash
        }


        // Désactive toutes les collisions d'un ennemi pour permettre au dash de passer à travers.
        private void DisableEnemyCollisions(GameObject enemy)
        {

            Collider[] colliders = enemy.GetComponentsInChildren<Collider>();
            foreach (Collider col in colliders)
            {
                col.enabled = false;
            }

            // Désactiver également le rigidbody pour éviter les interactions physiques
            Rigidbody rb = enemy.GetComponent<Rigidbody>();
            if (rb != null)
            {
                rb.isKinematic = true;
                rb.detectCollisions = false;
            }

            Rigidbody[] childRbs = enemy.GetComponentsInChildren<Rigidbody>();
            foreach (Rigidbody childRb in childRbs)
            {
                childRb.isKinematic = true;
                childRb.detectCollisions = false;
            }
        }

        private System.Collections.IEnumerator CleanupEnemyTracking(GameObject enemy)
        {
            yield return new WaitForSeconds(2f);
            if (enemy == null)
            {
                // L'ennemi a bien été détruit, on peut le retirer du tracking
                enemiesKilledByDash.Remove(enemy);
            }
        }

        // Vérifie si un ennemi a été tué par le dash
        public static bool WasKilledByDash(GameObject enemy)
        {
            return enemiesKilledByDash.Contains(enemy);
        }

        private void EndDash()
        {
            // Appliquer le momentum de sortie si activé
            if (conserveMomentum && fpsMovement != null)
            {
                // Calculer le momentum basé sur la vitesse du dash
                Vector3 dashMomentum = directionalDashDir * dashSpeed * momentumRetention;
                fpsMovement.ApplyExternalMomentum(dashMomentum);

                Debug.Log($"[DashSystem] Momentum conservé: {dashMomentum.magnitude:F1} m/s dans la direction {directionalDashDir}");
            }

            isDashing = false;
            dashTimer = 0f;
            cooldownTimer = 0f;
            targetFOV = defaultFOV;
        }

        private void UpdateFOV()
        {
            if (playerCamera != null)
            {
                playerCamera.fieldOfView = Mathf.Lerp(
                    playerCamera.fieldOfView,
                    targetFOV,
                    Time.deltaTime * fovTransitionSpeed
                );
            }
        }

        public bool CanDash => currentDashCharge >= 1f && !isDashing && (autoRegenerate ? cooldownTimer >= dashCooldown : true);

        public float DashCooldownProgress => Mathf.Clamp01(cooldownTimer / dashCooldown);

        public float CurrentDashCharge => currentDashCharge;

        // Appelé quand un ennemi spécial (DashEnergyEnemy) est tué
        public void OnDashEnemyKilled(float energyAmount)
        {
            float oldCharge = currentDashCharge;

            // Calculer l'énergie par ennemi (1 / nombre d'ennemis requis)
            float energyPerEnemy = 1f / Mathf.Max(1, enemiesRequiredForFullCharge);

            // Ajouter l'énergie (multipliée par le montant configuré sur l'ennemi)
            currentDashCharge = Mathf.Clamp01(currentDashCharge + (energyPerEnemy * energyAmount));

            Debug.Log($"[DashSystem] Dash rechargé! {oldCharge:P0} → {currentDashCharge:P0} (+{energyPerEnemy * energyAmount:P0})");
        }
    }
}

using UnityEngine;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using FPS; // EnemyHealth
namespace FPS
{

    // Système de dash directionnel
    // Permet au joueur de dasher dans la direction de la caméra et de tuer les ennemis sur son passage
    public class DashSystem : MonoBehaviour
    {
        [Header("Dash Settings")]
        [Tooltip("Vitesse du dash")]
        [SerializeField] private float dashSpeed = 25f;

        [Tooltip("Durée du dash en secondes")]
        [SerializeField] private float dashDuration = 0.4f;

        [Tooltip("Courbe de vitesse du dash (X = temps normalisé 0-1, Y = multiplicateur de vitesse)")]
        [SerializeField] private AnimationCurve dashSpeedCurve = AnimationCurve.EaseInOut(0f, 1f, 1f, 0.3f);

        [Header("Dash Charge Settings")]
        [Tooltip("Activer la régénération automatique du dash (désactiver pour forcer le kill d'ennemis)")]
        [SerializeField] private bool autoRegenerate = false;

        [Tooltip("Cooldown entre chaque dash en secondes (uniquement si autoRegenerate est activé)")]
        [SerializeField] private float dashCooldown = 1.5f;

        [Tooltip("Nombre d'ennemis spéciaux à tuer pour remplir complètement la barre de dash")]
        [SerializeField] private int enemiesRequiredForFullCharge = 3;

        [Tooltip("Charge de dash actuelle (0 à 1)")]
        [SerializeField] private float currentDashCharge = 1f;

        [Tooltip("Rayon de détection des ennemis pendant le dash")]
        [SerializeField] private float dashHitRadius = 1.0f;

        [Tooltip("Dégâts infligés aux ennemis touchés")]
        [SerializeField] private float dashDamage = 9999f;

        [Tooltip("LayerMask pour détecter les ennemis")]
        [SerializeField] private LayerMask enemyMask = ~0;

        [Header("Collision Settings")]
        [Tooltip("Angle maximum (en degrés) entre la direction du dash et la surface pour continuer le dash. Au-delà, le dash s'arrête.")]
        [SerializeField] private float maxCollisionAngle = 45f;

        [Tooltip("LayerMask pour les obstacles qui peuvent arrêter le dash")]
        [SerializeField] private LayerMask obstacleMask = ~0;

        [Tooltip("Distance de détection des obstacles devant le joueur")]
        [SerializeField] private float obstacleCheckDistance = 0.5f;

        [Header("FOV Settings")]
        [Tooltip("FOV pendant le dash")]
        [SerializeField] private float dashFOV = 90f;

        [Tooltip("Vitesse de transition du FOV")]
        [SerializeField] private float fovTransitionSpeed = 15f;

        [Header("Momentum Settings")]
        [Tooltip("Conserver l'énergie cinétique à la sortie du dash")]
        [SerializeField] private bool conserveMomentum = true;

        [Tooltip("Pourcentage du momentum du dash à conserver (0 à 1)")]
        [SerializeField] private float momentumRetention = 0.8f;

        [Header("References")]
        [SerializeField] private FPSPlayerController playerController;
        [SerializeField] private FPSMovement fpsMovement;
        [SerializeField] private Transform cameraTransform;
        [SerializeField] private SoundPlayer sound;

        private Camera playerCamera;
        private float defaultFOV;
        private float targetFOV;

        public bool isDashing = false;
        private float dashTimer = 0f;
        private float cooldownTimer = 0f;

        private Rigidbody rb;

        private static System.Collections.Generic.HashSet<GameObject> enemiesKilledByDash = new System.Collections.Generic.HashSet<GameObject>();

        // Runtime
        private Vector3 directionalDashDir;
        private Vector3 lastDashPosition;
        private readonly HashSet<GameObject> _hitThisDash = new HashSet<GameObject>();
        private static readonly RaycastHit[] _hitBuffer = new RaycastHit[32];

        private void Start()
        {
            if (playerController == null)
            {
                playerController = GetComponent<FPSPlayerController>();
                if (playerController == null)
                {
                    return;
                }
            }

            if (fpsMovement == null)
            {
                fpsMovement = GetComponent<FPSMovement>();
            }

            if (cameraTransform == null)
            {
                cameraTransform = playerController.CameraTransform;
                if (cameraTransform == null)
                {
                    return;
                }
            }

            if (cameraTransform != null)
            {
                playerCamera = cameraTransform.GetComponent<Camera>();
                if (playerCamera != null)
                {
                    defaultFOV = playerCamera.fieldOfView;
                    targetFOV = defaultFOV;
                }
            }

            rb = fpsMovement != null ? fpsMovement.Rb : GetComponent<Rigidbody>();

            if (rb == null)
            {
                rb = GetComponent<Rigidbody>();
                Debug.LogWarning("[DashSystem] Rigidbody obtenu directement car fpsMovement.Rb était null");
            }

            if (rb == null)
            {
                Debug.LogError("[DashSystem] Rigidbody non trouvé! Le dash ne fonctionnera pas.");
            }
        }

        private void Update()
        {
            // Mise à jour du cooldown
            if (autoRegenerate && cooldownTimer < dashCooldown)
            {
                cooldownTimer += Time.deltaTime;

                // Régénération automatique de la charge
                if (cooldownTimer >= dashCooldown && currentDashCharge < 1f)
                {
                    currentDashCharge = 1f;
                }
            }

            // Empêcher le dash pendant un stun
            var stunComp = GetComponent<PlayerStunAutoFire>();
            bool isStunned = stunComp != null && stunComp.IsStunned;

            // Gestion du dash
            if (isDashing)
            {
                HandleDash();
            }
            else
            {
                bool hasCharge = currentDashCharge >= 1f;
                bool cooldownReady = autoRegenerate ? (cooldownTimer >= dashCooldown) : true;

                if (!isStunned && Input.GetMouseButtonDown(1) && hasCharge && cooldownReady)
                {
                    StartDirectionalDash();
                }
            }

            // Gestion du FOV
            UpdateFOV();
        }

        private void FixedUpdate()
        {
            if (!isDashing || rb == null) return;

            // Vérifier les obstacles devant le joueur
            if (CheckObstacleCollision())
            {
                EndDash();
                return;
            }

            float dashProgress = Mathf.Clamp01(dashTimer / dashDuration);

            // Évaluer la courbe pour obtenir le multiplicateur de vitesse
            float speedMultiplier = dashSpeedCurve.Evaluate(dashProgress);

            // Mouvement en ligne droite selon la direction de dash avec la courbe appliquée
            Vector3 dashMovement = directionalDashDir * (dashSpeed * speedMultiplier * Time.fixedDeltaTime);

            Vector3 currentPos = transform.position;
            Vector3 nextPos = currentPos + dashMovement;
            Vector3 seg = nextPos - lastDashPosition;
            float segLen = seg.magnitude;
            if (segLen > 0.0001f)
            {
                int hits = Physics.SphereCastNonAlloc(
                    lastDashPosition,
                    dashHitRadius,
                    seg.normalized,
                    _hitBuffer,
                    segLen,
                    enemyMask,
                    QueryTriggerInteraction.Ignore
                );
                for (int i = 0; i < hits; i++)
                {
                    var h = _hitBuffer[i];
                    if (h.collider == null) continue;
                    var enemyHealth = h.collider.GetComponentInParent<EnemyHealth>() ?? h.collider.GetComponent<EnemyHealth>();
                    if (enemyHealth == null) continue;

                    var enemyRoot = enemyHealth.transform.root.gameObject;
                    if (_hitThisDash.Contains(enemyRoot)) continue;
                    _hitThisDash.Add(enemyRoot);

                    // Si c'est un ennemi électrique -> stun le joueur (auto-fire)
                    var electric = h.collider.GetComponentInParent<Ennemies.Effect.ElectricEnnemis>() ?? h.collider.GetComponent<Ennemies.Effect.ElectricEnnemis>();
                    if (electric != null)
                    {
                        var playerStun = GetComponent<PlayerStunAutoFire>();
                        if (playerStun == null) playerStun = gameObject.AddComponent<PlayerStunAutoFire>();
                        if (electric.OverrideAutoFireInterval)
                            playerStun.ApplyStun(electric.StunDuration, electric.StunAutoFireInterval);
                        else
                            playerStun.ApplyStun(electric.StunDuration);

                        // Arrêter le dash immédiatement à cause du stun électrique
                        EndDash();
                        return;
                    }

                    // Marquer comme kill par dash si le coup sera létal
                    bool willDie = enemyHealth.CurrentHealth <= dashDamage;
                    if (willDie)
                    {
                        enemiesKilledByDash.Add(enemyRoot);
                        StartCoroutine(CleanupEnemyTracking(enemyRoot));

                        // Désactiver immédiatement les collisions pour permettre le dash à travers
                        DisableEnemyCollisions(enemyRoot);
                    }

                    // Appliquer dégâts
                    // enemyHealth.TakeDamage(dashDamage, "Dash");
                    enemyHealth.TakeDamage(new DamageInfo(dashDamage, "Dash", DamageType.Dash));
                }
            }

            lastDashPosition = nextPos;
            rb.MovePosition(rb.position + dashMovement);
            Debug.DrawRay(transform.position, directionalDashDir * 3f, Color.cyan, 0.05f);
        }

        private void StartDirectionalDash()
        {
            Vector3 fwd;
            if (playerCamera != null)
            {
                Ray aimRay = playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
                fwd = aimRay.direction;
            }
            else if (cameraTransform != null)
            {
                fwd = cameraTransform.forward;
            }
            else
            {
                fwd = transform.forward;
            }

            if(sound != null)
            {
                sound.PlayOneShot("Dash");
            }

            directionalDashDir = fwd.normalized;

            currentDashCharge = 0f;

            // Mettre la vitesse de mouvement au maximum et désactiver le mouvement normal
            if (fpsMovement != null)
            {
                fpsMovement.SetSpeedToMax();
                fpsMovement.DisableMovement();
            }

            // Init timers/état
            isDashing = true;
            dashTimer = 0f;
            targetFOV = dashFOV;
            lastDashPosition = transform.position;
            _hitThisDash.Clear();
        }

        private void HandleDash()
        {
            dashTimer += Time.deltaTime;

            if (dashTimer >= dashDuration)
            {
                EndDash();
            }
        }

        // Vérifie si le dash doit être arrêté par une collision avec un obstacle à mauvais angle
        private bool CheckObstacleCollision()
        {
            // Raycast dans la direction du dash pour détecter les obstacles
            RaycastHit hit;
            float checkDistance = obstacleCheckDistance;

            // SphereCast pour détecter les obstacles devant le joueur avec un rayon similaire au dashHitRadius
            if (Physics.SphereCast(
                transform.position,
                dashHitRadius * 0.8f, // Légèrement plus petit pour éviter les faux positifs
                directionalDashDir,
                out hit,
                checkDistance,
                obstacleMask,
                QueryTriggerInteraction.Ignore))
            {
                // Ignorer si c'est un ennemi (ils sont gérés séparément)
                var enemyHealth = hit.collider.GetComponentInParent<EnemyHealth>() ?? hit.collider.GetComponent<EnemyHealth>();
                if (enemyHealth != null)
                {
                    return false; // Ne pas arrêter le dash pour les ennemis
                }

                // Calculer l'angle entre la direction du dash et la normale de la surface
                float angle = Vector3.Angle(directionalDashDir, -hit.normal);

                // Debug visuel
                Debug.DrawRay(hit.point, hit.normal * 2f, Color.red, 0.1f);
                Debug.DrawRay(hit.point, directionalDashDir * 2f, Color.yellow, 0.1f);

                // Si l'angle est trop abrupt (surface trop perpendiculaire à la direction du dash)
                if (angle > maxCollisionAngle)
                {
                    Debug.Log($"[DashSystem] Dash arrêté par collision ! Angle: {angle:F1}° (max: {maxCollisionAngle}°)");
                    return true; // Arrêter le dash
                }
            }

            return false; // Continuer le dash
        }


        // Désactive toutes les collisions d'un ennemi pour permettre au dash de passer à travers.
        private void DisableEnemyCollisions(GameObject enemy)
        {

            Collider[] colliders = enemy.GetComponentsInChildren<Collider>();
            foreach (Collider col in colliders)
            {
                col.enabled = false;
            }

            // Désactiver également le rigidbody pour éviter les interactions physiques
            Rigidbody enemyRb = enemy.GetComponent<Rigidbody>();
            if (enemyRb != null)
            {
                enemyRb.isKinematic = true;
                enemyRb.detectCollisions = false;
            }

            Rigidbody[] childRbs = enemy.GetComponentsInChildren<Rigidbody>();
            foreach (Rigidbody childRb in childRbs)
            {
                childRb.isKinematic = true;
                childRb.detectCollisions = false;
            }
        }

        private System.Collections.IEnumerator CleanupEnemyTracking(GameObject enemy)
        {
            yield return new WaitForSeconds(2f);
            if (enemy == null)
            {
                // L'ennemi a bien été détruit, on peut le retirer du tracking
                enemiesKilledByDash.Remove(enemy);
            }
        }

        // Vérifie si un ennemi a été tué par le dash
        public static bool WasKilledByDash(GameObject enemy)
        {
            return enemiesKilledByDash.Contains(enemy);
        }

        private void EndDash()
        {
            // Réactiver le mouvement normal
            if (fpsMovement != null)
            {
                fpsMovement.EnableMovement();
            }

            // Appliquer le momentum de sortie si activé
            if (conserveMomentum && fpsMovement != null)
            {
                // Calculer le momentum basé sur la vitesse du dash
                Vector3 dashMomentum = directionalDashDir * dashSpeed * momentumRetention;
                fpsMovement.ApplyExternalMomentum(dashMomentum);

                Debug.Log($"[DashSystem] Momentum conservé: {dashMomentum.magnitude:F1} m/s dans la direction {directionalDashDir}");
            }

            isDashing = false;
            dashTimer = 0f;
            cooldownTimer = 0f;
            targetFOV = defaultFOV;
        }

        private void UpdateFOV()
        {
            if (playerCamera != null)
            {
                playerCamera.fieldOfView = Mathf.Lerp(
                    playerCamera.fieldOfView,
                    targetFOV,
                    Time.deltaTime * fovTransitionSpeed
                );
            }
        }

        public bool CanDash => currentDashCharge >= 1f && !isDashing && (autoRegenerate ? cooldownTimer >= dashCooldown : true);

        public float DashCooldownProgress => Mathf.Clamp01(cooldownTimer / dashCooldown);

        public float CurrentDashCharge => currentDashCharge;

        // Appelé quand un ennemi spécial (DashEnergyEnemy) est tué
        public void OnDashEnemyKilled(float energyAmount)
        {
            float oldCharge = currentDashCharge;

            // Calculer l'énergie par ennemi (1 / nombre d'ennemis requis)
            float energyPerEnemy = 1f / Mathf.Max(1, enemiesRequiredForFullCharge);

            // Ajouter l'énergie (multipliée par le montant configuré sur l'ennemi)
            currentDashCharge = Mathf.Clamp01(currentDashCharge + (energyPerEnemy * energyAmount));

            Debug.Log($"[DashSystem] Dash rechargé! {oldCharge:P0} → {currentDashCharge:P0} (+{energyPerEnemy * energyAmount:P0})");
        }
    }
}

using FPS;
using UnityEngine;

[RequireComponent(typeof(PlayerHealth))]
public class Death : MonoBehaviour
{
    [SerializeField] private Transform spawnRoot;

    private PlayerHealth playerHealth;
    private CharacterController characterController;
    private Vector3 spawnPosition;
    private Quaternion spawnRotation;

    // Start is called once before the first execution of Update after the MonoBehaviour is created
    void Awake()
    {
        playerHealth = GetComponent<PlayerHealth>();
        characterController = GetComponent<CharacterController>();
        spawnRoot = spawnRoot != null ? spawnRoot : transform;
    }

    private void OnEnable()
    {
        if (playerHealth != null)
        {
            playerHealth.OnDeath.AddListener(HandleDeath);
        }
    }

    private void Start()
    {
        CacheSpawnPoint();
    }

    private void OnDisable()
    {
        if (playerHealth != null)
        {
            playerHealth.OnDeath.RemoveListener(HandleDeath);
        }
    }

    private void CacheSpawnPoint()
    {
        spawnPosition = spawnRoot.position;
        spawnRotation = spawnRoot.rotation;
    }

    public void SetSpawnPoint(Transform newSpawn)
    {
        if (newSpawn == null) return;
        spawnRoot = newSpawn;
        CacheSpawnPoint();
    }

    private void HandleDeath()
    {
        RespawnPlayer();
        playerHealth.ResetHealth();
    }

    private void RespawnPlayer()
    {
        bool controllerInitiallyEnabled = characterController != null && characterController.enabled;
        if (characterController != null)
        {
            characterController.enabled = false;
        }

        transform.SetPositionAndRotation(spawnPosition, spawnRotation);

        if (controllerInitiallyEnabled)
        {
            characterController.enabled = true;
        }
    }
}

using FPS;
using UnityEngine;

[RequireComponent(typeof(PlayerHealth))]
public class Death : MonoBehaviour
{
    [SerializeField] private Transform spawnRoot;

    private PlayerHealth playerHealth;
    private Rigidbody rb;
    private Vector3 spawnPosition;
    private Quaternion spawnRotation;

    // Start is called once before the first execution of Update after the MonoBehaviour is created
    void Awake()
    {
        playerHealth = GetComponent<PlayerHealth>();
        rb = GetComponent<Rigidbody>();
        spawnRoot = spawnRoot != null ? spawnRoot : transform;
    }

    private void OnEnable()
    {
        if (playerHealth != null)
        {
            playerHealth.OnDeath.AddListener(HandleDeath);
        }
    }

    private void Start()
    {
        CacheSpawnPoint();
    }

    private void OnDisable()
    {
        if (playerHealth != null)
        {
            playerHealth.OnDeath.RemoveListener(HandleDeath);
        }
    }

    private void CacheSpawnPoint()
    {
        spawnPosition = spawnRoot.position;
        spawnRotation = spawnRoot.rotation;
    }

    public void SetSpawnPoint(Transform newSpawn)
    {
        if (newSpawn == null) return;
        spawnRoot = newSpawn;
        CacheSpawnPoint();
    }

    private void HandleDeath()
    {
        RespawnPlayer();
        playerHealth.ResetHealth();
    }

    private void RespawnPlayer()
    {
        if (rb != null)
        {
            // Reset velocity before teleporting
            rb.linearVelocity = Vector3.zero;
            rb.angularVelocity = Vector3.zero;

            // Teleport using Rigidbody
            rb.position = spawnPosition;
            rb.rotation = spawnRotation;
        }
        else
        {
            transform.SetPositionAndRotation(spawnPosition, spawnRotation);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

namespace FPS
{
    // Gère la santé de l'ennemi avec zones de dégâts et tracking des hits.
    public class EnemyHealth : MonoBehaviour
    {
        [Header("Health Settings")]
        [SerializeField] private float maxHealth = 100f;
        [SerializeField] private float currentHealth;

        [Header("Spawn Invulnerability")]
        [Tooltip("Durée d'invulnérabilité après l'apparition (secondes)")]
        [SerializeField] private float spawnInvulnerabilityDuration = 0f;
        [Tooltip("Si vrai, invulnérable à tous les types de dégâts pendant l'invulnérabilité; sinon seulement aux balles")]
        [SerializeField] private bool spawnInvulnerableAllDamage = false;
        private float spawnInvulnerableUntil;

        [Header("Hit Tracking")]
        [SerializeField] private Dictionary<string, int> zoneHitCount = new Dictionary<string, int>();

        [Header("Events")]
        public UnityEvent OnDeath;
        public UnityEvent<float, string> OnDamageTaken;

        private bool isDead;
        private WaveManager waveManager;

        // Centralisation: suivi de l'origine des dégâts/kill
        private DamageType lastHitType = DamageType.Other;
        private DamageType lastKillType = DamageType.Other;
        private Transform lastAttacker;

        private void Awake()
        {
            currentHealth = maxHealth;
            spawnInvulnerableUntil = Time.time + Mathf.Max(0f, spawnInvulnerabilityDuration);
            waveManager = FindFirstObjectByType<WaveManager>();
        }

        private void EnsureWaveManager()
        {
            if (waveManager == null)
            {
                waveManager = FindFirstObjectByType<WaveManager>();
            }
        }

        private bool IsSpawnInvulnerableFor(DamageType type)
        {
            if (Time.time < spawnInvulnerableUntil)
            {
                if (spawnInvulnerableAllDamage) return true;
                return type == DamageType.Bullet;
            }
            return false;
        }

        // Nouveau pipeline: tente d'appliquer un dégât détaillé. Retourne true si appliqué.
        public bool TryApplyDamage(DamageInfo info)
        {
            if (isDead) return false;
            // Intercepteurs (ex: MagicEnemy) — peuvent bloquer et déclencher des effets (renvoi)
            bool allow = true;
            var interceptors = GetComponents<IDamageInterceptor>();
            if (interceptors != null && interceptors.Length > 0)
            {
                for (int i = 0; i < interceptors.Length; i++)
                {
                    try { allow = interceptors[i].OnBeforeDamage(ref info) && allow; } catch {}
                }
            }
            if (!allow) return false;

            // Invulnérabilité de spawn propre (bloque sans "retirer puis remettre")
            if (IsSpawnInvulnerableFor(info.type))
            {
                return false;
            }

            // Appliquer
            float damage = Mathf.Max(0f, info.amount);
            string zoneName = string.IsNullOrWhiteSpace(info.zoneName) ? "Body" : info.zoneName;
            currentHealth -= damage;

            // Centralisation: enregistrer la source du dernier coup
            lastHitType = info.type;
            lastAttacker = info.attacker;

            // Enregistrer le hit
            string key = NormalizeZoneKey(zoneName);
            if (!zoneHitCount.ContainsKey(key)) zoneHitCount[key] = 0;
            zoneHitCount[key]++;

            // Événement de dégâts pris (après application)
            OnDamageTaken?.Invoke(damage, zoneName);

            // Déclencher l'effet électrique si c'est un ennemi électrique mais seulement si les dégâts ne viennent pas déjà d'une décharge électrique
            if (info.type != DamageType.Electric)
            {
                var electricEnemy = GetComponent<Ennemies.Effect.ElectricEnnemis>();
                if (electricEnemy != null)
                {
                    electricEnemy.TriggerElectricDischarge();
                }
            }

            if (currentHealth <= 0)
            {
                // Centralisation: consigner le type de kill avant la mort
                lastKillType = info.type;
                Die();
            }
            return true;
        }

        // Compat: Inflige des dégâts à l'ennemi et enregistre la zone touchée.
        public void TakeDamage(float damage, string zoneName)
        {
            // Considéré comme dégât de balle par défaut
            var info = new DamageInfo(damage, zoneName, DamageType.Bullet);
            TryApplyDamage(info);
        }

        // Overload simple (zone par défaut)
        public void TakeDamage(float damage)
        {
            TakeDamage(damage, "Body");
        }

        // Nouveau: API directe avec DamageInfo
        public void TakeDamage(in DamageInfo info)
        {
            TryApplyDamage(info);
        }

        private void Die()
        {
            if (isDead) return;

            isDead = true;
            OnDeath?.Invoke();

            // Notifier le wave manager qu'un ennemi est mort
            EnsureWaveManager();
            if (waveManager != null)
            {
                waveManager.OnEnemyDeath(this);
            }

            Destroy(gameObject);
        }

        private static string NormalizeZoneKey(string zone)
        {
            return string.IsNullOrWhiteSpace(zone) ? string.Empty : zone.Trim().ToLowerInvariant();
        }

        public float CurrentHealth => currentHealth;
        public float MaxHealth => maxHealth;
        public bool IsDead => isDead;
        public Dictionary<string, int> ZoneHitCount => zoneHitCount;

        // Centralisation: exposer la cause de mort et la source
        public DamageType LastHitType => lastHitType;
        public DamageType LastKillType => lastKillType;
        public Transform LastAttacker => lastAttacker;

        // Tue immédiatement cet ennemi sans enregistrer de hit
        public void KillImmediate()
        {
            if (isDead) return;
            currentHealth = 0f;
            lastKillType = DamageType.Other;
            Die();
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

namespace FPS
{
    // Gère la santé de l'ennemi avec zones de dégâts et tracking des hits.
    public class EnemyHealth : MonoBehaviour
    {
        [Header("Health Settings")]
        [SerializeField] private float maxHealth = 100f;
        [SerializeField] private float currentHealth;

        [Header("Spawn Invulnerability")]
        [Tooltip("Durée d'invulnérabilité après l'apparition (secondes)")]
        [SerializeField] private float spawnInvulnerabilityDuration = 0f;
        [Tooltip("Si vrai, invulnérable à tous les types de dégâts pendant l'invulnérabilité; sinon seulement aux balles")]
        [SerializeField] private bool spawnInvulnerableAllDamage = false;
        private float spawnInvulnerableUntil;

        [Header("Hit Tracking")]
        [SerializeField] private Dictionary<string, int> zoneHitCount = new Dictionary<string, int>();

        [Header("Events")]
        public UnityEvent OnDeath;
        public UnityEvent<float, string> OnDamageTaken;

        private bool isDead;
        private WaveManager waveManager;

        // Centralisation: suivi de l'origine des dégâts/kill
        private DamageType lastHitType = DamageType.Other;
        private DamageType lastKillType = DamageType.Other;
        private Transform lastAttacker;

        private void Awake()
        {
            currentHealth = maxHealth;
            spawnInvulnerableUntil = Time.time + Mathf.Max(0f, spawnInvulnerabilityDuration);
            waveManager = FindFirstObjectByType<WaveManager>();
        }

        private void EnsureWaveManager()
        {
            if (waveManager == null)
            {
                waveManager = FindFirstObjectByType<WaveManager>();
            }
        }

        private bool IsSpawnInvulnerableFor(DamageType type)
        {
            if (Time.time < spawnInvulnerableUntil)
            {
                if (spawnInvulnerableAllDamage) return true;
                return type == DamageType.Bullet;
            }
            return false;
        }

        // Nouveau pipeline: tente d'appliquer un dégât détaillé. Retourne true si appliqué.
        public bool TryApplyDamage(DamageInfo info)
        {
            if (isDead) return false;
            // Intercepteurs (ex: MagicEnemy) — peuvent bloquer et déclencher des effets (renvoi)
            bool allow = true;
            var interceptors = GetComponents<IDamageInterceptor>();
            if (interceptors != null && interceptors.Length > 0)
            {
                for (int i = 0; i < interceptors.Length; i++)
                {
                    try { allow = interceptors[i].OnBeforeDamage(ref info) && allow; } catch {}
                }
            }
            if (!allow) return false;

            // Invulnérabilité de spawn propre (bloque sans "retirer puis remettre")
            if (IsSpawnInvulnerableFor(info.type))
            {
                return false;
            }

            // Appliquer
            float damage = Mathf.Max(0f, info.amount);
            string zoneName = string.IsNullOrWhiteSpace(info.zoneName) ? "Body" : info.zoneName;
            currentHealth -= damage;

            // Centralisation: enregistrer la source du dernier coup
            lastHitType = info.type;
            lastAttacker = info.attacker;

            // Enregistrer le hit
            string key = NormalizeZoneKey(zoneName);
            if (!zoneHitCount.ContainsKey(key)) zoneHitCount[key] = 0;
            zoneHitCount[key]++;

            // Événement de dégâts pris (après application)
            OnDamageTaken?.Invoke(damage, zoneName);

            // Déclencher l'effet électrique si c'est un ennemi électrique mais seulement si les dégâts ne viennent pas déjà d'une décharge électrique
            if (info.type != DamageType.Electric)
            {
                var electricEnemy = GetComponent<Ennemies.Effect.ElectricEnnemis>();
                if (electricEnemy != null)
                {
                    electricEnemy.TriggerElectricDischarge();
                }
            }

            // Appliquer le knockback si c'est un dash et que l'ennemi ne résiste pas
            if (info.type == DamageType.Dash)
            {
                TryApplyDashKnockback(info);
            }

            if (currentHealth <= 0)
            {
                // Centralisation: consigner le type de kill avant la mort
                lastKillType = info.type;
                Die();
            }
            return true;
        }

        // Compat: Inflige des dégâts à l'ennemi et enregistre la zone touchée.
        public void TakeDamage(float damage, string zoneName)
        {
            // Considéré comme dégât de balle par défaut
            var info = new DamageInfo(damage, zoneName, DamageType.Bullet);
            TryApplyDamage(info);
        }

        // Overload simple (zone par défaut)
        public void TakeDamage(float damage)
        {
            TakeDamage(damage, "Body");
        }

        // Nouveau: API directe avec DamageInfo
        public void TakeDamage(in DamageInfo info)
        {
            TryApplyDamage(info);
        }

        private void Die()
        {
            if (isDead) return;

            isDead = true;
            OnDeath?.Invoke();

            // Notifier le wave manager qu'un ennemi est mort
            EnsureWaveManager();
            if (waveManager != null)
            {
                waveManager.OnEnemyDeath(this);
            }

            Destroy(gameObject);
        }

        private static string NormalizeZoneKey(string zone)
        {
            return string.IsNullOrWhiteSpace(zone) ? string.Empty : zone.Trim().ToLowerInvariant();
        }

        public float CurrentHealth => currentHealth;
        public float MaxHealth => maxHealth;
        public bool IsDead => isDead;
        public Dictionary<string, int> ZoneHitCount => zoneHitCount;

        // Centralisation: exposer la cause de mort et la source
        public DamageType LastHitType => lastHitType;
        public DamageType LastKillType => lastKillType;
        public Transform LastAttacker => lastAttacker;

        // Tue immédiatement cet ennemi sans enregistrer de hit
        public void KillImmediate()
        {
            if (isDead) return;
            currentHealth = 0f;
            lastKillType = DamageType.Other;
            Die();
        }

        /// <summary>
        /// Tente d'appliquer le knockback lors d'un dash si l'ennemi n'y résiste pas.
        /// </summary>
        private void TryApplyDashKnockback(DamageInfo info)
        {
            // Vérifier si l'ennemi résiste au dash (ex: ElectricEnnemis avec ResistToDash)
            var electricEnemy = GetComponent<Ennemies.Effect.ElectricEnnemis>();
            if (electricEnemy != null && electricEnemy.ResistToDash)
            {
                return;
            }

            // Récupérer ou créer le composant de knockback
            var knockback = GetComponent<EnemyKnockback>();
            if (knockback == null)
            {
                // Auto-ajouter le Rigidbody s'il n'existe pas
                var rb = GetComponent<Rigidbody>();
                if (rb == null)
                {
                    rb = gameObject.AddComponent<Rigidbody>();
                    rb.isKinematic = true;
                    rb.interpolation = RigidbodyInterpolation.Interpolate;
                    rb.constraints = RigidbodyConstraints.FreezeRotation;
                }

                // Auto-ajouter le composant EnemyKnockback
                knockback = gameObject.AddComponent<EnemyKnockback>();
            }

            if (knockback.ResistToKnockback)
            {
                return;
            }

            // Calculer la direction du knockback (depuis l'attaquant vers l'ennemi)
            Vector3 knockbackDirection;
            if (info.attacker != null)
            {
                knockbackDirection = (transform.position - info.attacker.position).normalized;
            }
            else if (info.hitNormal != Vector3.zero)
            {
                // Utiliser l'inverse de la normale de hit comme direction
                knockbackDirection = -info.hitNormal.normalized;
            }
            else
            {
                // Fallback: direction par défaut (vers l'arrière de l'ennemi)
                knockbackDirection = -transform.forward;
            }

            // Récupérer les paramètres de knockback depuis le DashCible du joueur
            float force = 15f;      // Valeur par défaut
            float duration = 0.5f;  // Valeur par défaut
            bool affectsY = false;  // Valeur par défaut

            // Essayer de récupérer les paramètres du DashDefinition via le joueur
            if (info.attacker != null)
            {
                var dashCible = info.attacker.GetComponent<DashCible>();
                if (dashCible != null)
                {
                    var dashDef = GetDashDefinitionFromPlayer(dashCible);
                    if (dashDef != null)
                    {
                        force = dashDef.knockbackForce;
                        duration = dashDef.knockbackDuration;
                        affectsY = dashDef.knockbackAffectsYAxis;
                    }
                }
            }

            // Appliquer le knockback
            knockback.ApplyKnockback(knockbackDirection, force, duration, affectsY);
        }

        /// <summary>
        /// Récupère le DashDefinition depuis le DashCible via réflexion (pour éviter de modifier DashCible).
        /// </summary>
        private DashDefinition GetDashDefinitionFromPlayer(DashCible dashCible)
        {
            // Utiliser la réflexion pour accéder au champ privé dashDefinition
            var field = typeof(DashCible).GetField("dashDefinition", 
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            if (field != null)
            {
                return field.GetValue(dashCible) as DashDefinition;
            }
            return null;
        }
    }
}

using UnityEngine;

namespace FPS
{
    /// <summary>
    /// Gère la rotation de la caméra et le lean (inclinaison)
    /// </summary>
    public class FPSMouseLook : MonoBehaviour
    {
        [Header("Camera Settings")]
        [SerializeField] private Transform cameraTransform;
        [SerializeField] private float mouseSensitivity = 2f;
        [SerializeField] private float minVerticalAngle = -80f;
        [SerializeField] private float maxVerticalAngle = 80f;

        [Header("Lean Settings")]
        [SerializeField] private float leanAngle = 15f;
        [SerializeField] private float leanInputAngle = 20f;
        [SerializeField] private float leanSpeed = 8f;

        private float verticalRotation = 0f;
        private float currentLean = 0f;

        private void Awake()
        {
            // Créer la caméra si elle n'existe pas
            if (cameraTransform == null)
            {
                GameObject camObj = new GameObject("PlayerCamera");
                camObj.transform.SetParent(transform);
                camObj.transform.localPosition = new Vector3(0, 0.8f, 0);
                cameraTransform = camObj.transform;

                Camera createdCam = camObj.AddComponent<Camera>();
                createdCam.fieldOfView = 60f;
                camObj.tag = "MainCamera";
            }

            Cursor.lockState = CursorLockMode.Locked;
            Cursor.visible = false;
        }

        public void Look(Vector2 lookInput, Vector2 moveInput, bool leanLeft, bool leanRight)
        {
            // Rotation horizontale (corps du joueur)
            float mouseX = lookInput.x * mouseSensitivity;
            transform.Rotate(Vector3.up * mouseX);

            // Rotation verticale (caméra)
            float mouseY = lookInput.y * mouseSensitivity;
            verticalRotation -= mouseY;
            verticalRotation = Mathf.Clamp(verticalRotation, minVerticalAngle, maxVerticalAngle);

            // Lean (inclinaison)
            float targetLean = 0f;
            if (Mathf.Abs(moveInput.x) > 0.01f)
            {
                targetLean = Mathf.Clamp(moveInput.x, -1f, 1f) * leanAngle;
            }
            if (leanLeft) targetLean = leanInputAngle;
            if (leanRight) targetLean = -leanInputAngle;

            currentLean = Mathf.Lerp(currentLean, targetLean, Time.deltaTime * leanSpeed);

            // Appliquer les rotations à la caméra
            cameraTransform.localRotation = Quaternion.Euler(verticalRotation, 0f, currentLean);
        }

        public Transform CameraTransform => cameraTransform;
    }
}

using UnityEngine;

namespace FPS
{
    /// <summary>
    /// Gère la rotation de la caméra et le lean (inclinaison)
    /// </summary>
    public class FPSMouseLook : MonoBehaviour
    {
        [Header("Camera Settings")]
        [SerializeField] private Transform cameraTransform;
        [SerializeField] private float mouseSensitivity = 2f;
        [SerializeField] private float minVerticalAngle = -80f;
        [SerializeField] private float maxVerticalAngle = 80f;

        [Header("Lean Settings")]
        [SerializeField] private float leanAngle = 15f;
        [SerializeField] private float leanInputAngle = 20f;
        [SerializeField] private float leanSpeed = 8f;

        private float verticalRotation;
        private float currentLean;
        private float yaw;

        private void Awake()
        {
            // Créer la caméra si elle n'existe pas
            if (cameraTransform == null)
            {
                GameObject camObj = new GameObject("PlayerCamera");
                camObj.transform.SetParent(transform);
                camObj.transform.localPosition = new Vector3(0, 0.8f, 0);
                cameraTransform = camObj.transform;

                Camera createdCam = camObj.AddComponent<Camera>();
                createdCam.fieldOfView = 60f;
                camObj.tag = "MainCamera";
            }

            Cursor.lockState = CursorLockMode.Locked;
            Cursor.visible = false;

            // Initialiser avec la rotation actuelle
            yaw = transform.eulerAngles.y;
            verticalRotation = 0f;
        }

        public void Look(Vector2 lookInput, Vector2 moveInput, bool leanLeft, bool leanRight)
        {
            // Rotation horizontale (corps du joueur) - appliquée directement au transform
            float mouseX = lookInput.x * mouseSensitivity;
            yaw += mouseX;
            transform.rotation = Quaternion.Euler(0f, yaw, 0f);

            // Rotation verticale (caméra)
            float mouseY = lookInput.y * mouseSensitivity;
            verticalRotation -= mouseY;
            verticalRotation = Mathf.Clamp(verticalRotation, minVerticalAngle, maxVerticalAngle);

            // Lean (inclinaison)
            float targetLean = 0f;
            if (Mathf.Abs(moveInput.x) > 0.01f)
            {
                targetLean = Mathf.Clamp(moveInput.x, -1f, 1f) * leanAngle;
            }
            if (leanLeft) targetLean = leanInputAngle;
            if (leanRight) targetLean = -leanInputAngle;

            currentLean = Mathf.Lerp(currentLean, targetLean, Time.deltaTime * leanSpeed);

            // Appliquer les rotations à la caméra
            cameraTransform.localRotation = Quaternion.Euler(verticalRotation, 0f, currentLean);
        }

        public Transform CameraTransform => cameraTransform;
    }
}

using UnityEngine;
using UnityEngine;
using UnityEngine.Events;

namespace FPS
{
    /// Gère le mouvement du joueur
    [RequireComponent(typeof(CharacterController))]
    public class FPSMovement : MonoBehaviour
    {
        [Header("Events")]
        public UnityEvent<float> OnSpeedChanged = new UnityEvent<float>();

        [Header("Movement Settings")]
        [SerializeField] private float moveSpeed = 5f;
        [SerializeField] private float sprintSpeed = 8f;
        [SerializeField] private float jumpHeight = 1.5f;
        [SerializeField] private float gravity = -9.81f;
        [SerializeField] private float gravityMultiplier = 2f;
        [SerializeField] private float increaseSpeedFactor = 25f;
        [SerializeField] private float speedLimit = 20f;

        [Header("Jump Settings")]
        [SerializeField, Tooltip("Temps après avoir quitté le sol pendant lequel on peut encore sauter")]
        private float coyoteTime = 0.15f;

        private float defaultMoveSpeed;

        [Header("Air Control")]
        [SerializeField, Tooltip("Contrôle en l'air (0 = aucun, 1 = identique au sol)")]
        private float airControlFactor = 0.4f;
        [SerializeField, Tooltip("Conserver la vitesse horizontale lors du saut")]
        private bool preserveJumpMomentum = false;
        [SerializeField, Tooltip("Multiplicateur de momentum lors du saut (1 = vitesse normale, >1 = boost)")]
        private float jumpMomentumMultiplier = 1f;
        [SerializeField, Tooltip("Vitesse maximale en l'air")]
        private float maxAirSpeed = 10f;

        [Header("Ground Check")]
        [SerializeField] private Transform groundCheck;
        [SerializeField] private float groundDistance = 0.4f;
        [SerializeField] private LayerMask groundMask;

        [Header("External Momentum")]
        [SerializeField, Tooltip("Facteur de dissipation appliqué au momentum externe (0 = sans dissipation).")]
        private float externalMomentumDamping = 12f;
        [SerializeField, Tooltip("Durée pendant laquelle la composante verticale du momentum est conservée même si le joueur est au sol.")]
        private float externalMomentumGroundGrace = 0.08f;

        private CharacterController controller;
        private Vector3 velocity;
        private Vector3 moveDirection = Vector3.zero;
        private Vector3 jumpMomentum = Vector3.zero;
        private Vector3 externalMomentum = Vector3.zero;
        private float externalMomentumGroundTimer;
        private bool isGrounded;
        private float coyoteTimeCounter;

        public bool IsGrounded => isGrounded;
        public bool IsMoving { get; private set; }
        public float CurrentSpeed { get; private set; }

        // Méthode pour forcer la vitesse au max (utilisée par le dash)
        public void SetSpeedToMax()
        {
            moveSpeed = speedLimit;
        }

        // Méthode pour appliquer un momentum externe (utilisée par le dash)
        public void ApplyExternalMomentum(Vector3 momentum)
        {
            externalMomentum = momentum;
            externalMomentumGroundTimer = externalMomentumGroundGrace;
            moveSpeed = Mathf.Max(moveSpeed, momentum.magnitude);
        }

        private void Awake()
        {
            controller = GetComponent<CharacterController>();

            defaultMoveSpeed = moveSpeed;
        }

        private void Update()
        {
            IncreaseSpeed();
            HandleGroundCheck();
        }

        // Cette méthode sera appelée par le PlayerController

        private void IncreaseSpeed()
        {
            float previousSpeed = moveSpeed;

            if (IsMoving)
            {
                if (moveSpeed < speedLimit)
                {
                    moveSpeed += increaseSpeedFactor * Time.deltaTime;
                    if (CurrentSpeed > maxAirSpeed)
                    {
                        CurrentSpeed = maxAirSpeed;
                    }
                }
            }
            else
            {
                moveSpeed = defaultMoveSpeed;
            }

            if (!Mathf.Approximately(previousSpeed, moveSpeed))
            {
                OnSpeedChanged?.Invoke(moveSpeed);
            }
        }

        public void Move(Vector2 input, bool sprint, bool jump)
        {
            // Calculer la direction de mouvement
            Vector3 desired = (transform.right * input.x + transform.forward * input.y);
            float desiredMag = desired.magnitude;
            if (desiredMag > 1f) desired /= desiredMag;

            CurrentSpeed = sprint ? sprintSpeed : moveSpeed;
            IsMoving = desired.sqrMagnitude > 0.01f;

            if (isGrounded)
            {
                // Réinitialiser le momentum au sol
                jumpMomentum = Vector3.zero;

                // Mouvement au sol
                if (desired.sqrMagnitude > 0f)
                {
                    controller.Move(desired * (CurrentSpeed * Time.deltaTime));
                }

                // Saut
                if (jump)
                {
                    velocity.y = Mathf.Sqrt(jumpHeight * -2f * gravity); //

                    // Capturer le momentum actuel pour le préserver en l'air
                    if (preserveJumpMomentum && desired.sqrMagnitude > 0f)
                    {
                        jumpMomentum = desired * CurrentSpeed * jumpMomentumMultiplier;
                    }

                    // Consommer le coyote time
                    coyoteTimeCounter = 0f;
                }
            }
            else
            {
                // Permettre le saut pendant le coyote time
                if (jump && coyoteTimeCounter > 0f)
                {
                    velocity.y = Mathf.Sqrt(jumpHeight * -2f * gravity);

                    // Capturer le momentum actuel pour le préserver en l'air
                    if (preserveJumpMomentum && desired.sqrMagnitude > 0f)
                    {
                        jumpMomentum = desired * CurrentSpeed * jumpMomentumMultiplier;
                    }

                    // Consommer le coyote time
                    coyoteTimeCounter = 0f;
                }

                // En l'air
                if (preserveJumpMomentum && jumpMomentum.sqrMagnitude > 0f)
                {
                    // Appliquer le momentum capturé au moment du saut
                    controller.Move(jumpMomentum * Time.deltaTime);

                    // Permettre un contrôle limité en l'air en PLUS du momentum
                    if (desired.sqrMagnitude > 0f)
                    {
                        controller.Move(desired * (CurrentSpeed * airControlFactor * Time.deltaTime));
                    }
                }
                else
                {
                    Vector3 airMove = desired * CurrentSpeed * airControlFactor;
                    moveDirection.x = Mathf.Lerp(moveDirection.x, airMove.x, airControlFactor);
                    moveDirection.z = Mathf.Lerp(moveDirection.z, airMove.z, airControlFactor);

                    controller.Move(new Vector3(moveDirection.x, 0, moveDirection.z) * Time.deltaTime);
                }
            }

            ProcessExternalMomentum();
            velocity.y += gravity * gravityMultiplier * Time.deltaTime;
            controller.Move(new Vector3(0, velocity.y, 0) * Time.deltaTime);
        }

        private void HandleGroundCheck()
        {
            if (groundCheck != null && groundMask != 0)
            {
                isGrounded = Physics.CheckSphere(groundCheck.position, groundDistance, groundMask);
            }
            else
            {
                isGrounded = controller.isGrounded;
            }

            // Gérer le coyote time
            if (isGrounded)
            {
                coyoteTimeCounter = coyoteTime;
            }
            else
            {
                coyoteTimeCounter -= Time.deltaTime;
            }

            // Réinitialiser la vélocité verticale au sol
            if (isGrounded && velocity.y < 0)
            {
                velocity.y = -2f;
            }
        }

        private void ProcessExternalMomentum()
        {
            if (externalMomentum.sqrMagnitude <= 1e-4f)
                return;

            if (externalMomentumGroundTimer > 0f)
                externalMomentumGroundTimer -= Time.deltaTime;

            if (isGrounded && externalMomentumGroundTimer <= 0f && externalMomentum.y > 0f)
                externalMomentum.y = 0f;

            controller.Move(externalMomentum * Time.deltaTime);

            float damping = externalMomentumDamping;
            if (isGrounded && externalMomentumGroundTimer <= 0f)
                damping *= 1.5f;

            if (damping > 0f)
            {
                externalMomentum = Vector3.MoveTowards(externalMomentum, Vector3.zero, damping * Time.deltaTime);
            }

            if (isGrounded && externalMomentumGroundTimer <= 0f && Mathf.Abs(externalMomentum.y) < 0.01f)
                externalMomentum.y = 0f;
        }

        public CharacterController Controller => controller;
    }
}

using UnityEngine;
using UnityEngine.Events;

namespace FPS
{
    /// Gère le mouvement du joueur avec Rigidbody
    [RequireComponent(typeof(Rigidbody))]
    [RequireComponent(typeof(CapsuleCollider))]
    public class FPSMovement : MonoBehaviour
    {
        [Header("Events")]
        public UnityEvent<float> OnSpeedChanged = new UnityEvent<float>();

        [Header("Movement Settings")]
        [SerializeField] private float moveSpeed = 5f;
        [SerializeField] private float sprintSpeed = 8f;
        [SerializeField] private float jumpHeight = 1.5f;
        [SerializeField] private float gravity = -9.81f;
        [SerializeField] private float gravityMultiplier = 2f;
        [SerializeField] private float maxFallSpeed = -20f;
        [SerializeField] private float increaseSpeedFactor = 25f;
        [SerializeField] private float speedLimit = 20f;

        [Header("Jump Settings")]
        [SerializeField, Tooltip("Temps après avoir quitté le sol pendant lequel on peut encore sauter")]
        private float coyoteTime = 0.15f;

        private float defaultMoveSpeed;

        [Header("Air Control")]
        [SerializeField, Tooltip("Contrôle en l'air (0 = aucun, 1 = identique au sol)")]
        private float airControlFactor = 0.4f;
        [SerializeField, Tooltip("Conserver la vitesse horizontale lors du saut")]
        private bool preserveJumpMomentum = false;
        [SerializeField, Tooltip("Multiplicateur de momentum lors du saut (1 = vitesse normale, >1 = boost)")]
        private float jumpMomentumMultiplier = 1f;
        [SerializeField, Tooltip("Vitesse maximale en l'air")]
        private float maxAirSpeed = 10f;

        [Header("Ground Check")]
        [SerializeField] private Transform groundCheck;
        [SerializeField] private float groundDistance = 0.4f;
        [SerializeField] private LayerMask groundMask;

        [Header("External Momentum")]
        [SerializeField, Tooltip("Facteur de dissipation appliqué au momentum externe (0 = sans dissipation).")]
        private float externalMomentumDamping = 12f;
        [SerializeField, Tooltip("Durée pendant laquelle la composante verticale du momentum est conservée même si le joueur est au sol.")]
        private float externalMomentumGroundGrace = 0.08f;

        private Rigidbody rb;
        private CapsuleCollider capsuleCollider;
        private Vector3 velocity;
        private Vector3 moveDirection = Vector3.zero;
        private Vector3 jumpMomentum = Vector3.zero;
        private Vector3 externalMomentum = Vector3.zero;
        private float externalMomentumGroundTimer;
        private bool isGrounded;
        private float coyoteTimeCounter;

        // Variables pour stocker les inputs entre Update et FixedUpdate
        private Vector2 inputMove;
        private bool inputSprint;
        private bool jumpRequested;

        // Flag pour désactiver le mouvement normal (pendant le dash)
        private bool movementDisabled;

        public bool IsGrounded => isGrounded;
        public bool IsMoving { get; private set; }
        public float CurrentSpeed { get; private set; }

        // Méthode pour forcer la vitesse au max (utilisée par le dash)
        public void SetSpeedToMax()
        {
            moveSpeed = speedLimit;
        }

        // Méthode pour appliquer un momentum externe (utilisée par le dash)
        public void ApplyExternalMomentum(Vector3 momentum)
        {
            externalMomentum = momentum;
            externalMomentumGroundTimer = externalMomentumGroundGrace;
            moveSpeed = Mathf.Max(moveSpeed, momentum.magnitude);
        }

        // Désactiver le mouvement normal (pendant le dash)
        public void DisableMovement()
        {
            movementDisabled = true;
            velocity.y = 0f; // Reset la gravité
            Debug.Log("[FPSMovement] Mouvement désactivé");
        }

        // Réactiver le mouvement normal (après le dash)
        public void EnableMovement()
        {
            if (movementDisabled)
            {
                Debug.Log("[FPSMovement] Mouvement réactivé");
            }
            movementDisabled = false;
        }

        // Propriété pour vérifier si le mouvement est désactivé
        public bool IsMovementDisabled => movementDisabled;

        private void Awake()
        {
            rb = GetComponent<Rigidbody>();
            capsuleCollider = GetComponent<CapsuleCollider>();

            // Configuration du Rigidbody pour un contrôle FPS
            rb.interpolation = RigidbodyInterpolation.Interpolate;
            rb.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
            rb.constraints = RigidbodyConstraints.FreezeRotation; // Freeze toutes les rotations
            rb.useGravity = false; // On gère la gravité manuellement
            rb.linearDamping = 0f; // Pas de résistance au mouvement
            rb.angularDamping = 0f;

            // Créer un PhysicMaterial sans friction pour éviter le ralentissement sur les surfaces
            PhysicsMaterial frictionlessMat = new PhysicsMaterial("PlayerNoFriction")
            {
                dynamicFriction = 0f,
                staticFriction = 0f,
                frictionCombine = PhysicsMaterialCombine.Minimum,
                bounciness = 0f,
                bounceCombine = PhysicsMaterialCombine.Minimum
            };
            capsuleCollider.material = frictionlessMat;

            defaultMoveSpeed = moveSpeed;
        }

        private void Update()
        {
            IncreaseSpeed();
            HandleGroundCheck();
        }

        private void FixedUpdate()
        {
            ApplyMovement();
        }

        private void IncreaseSpeed()
        {
            float previousSpeed = moveSpeed;

            if (IsMoving)
            {
                if (moveSpeed < speedLimit)
                {
                    moveSpeed += increaseSpeedFactor * Time.deltaTime;
                    if (CurrentSpeed > maxAirSpeed)
                    {
                        CurrentSpeed = maxAirSpeed;
                    }
                }
            }
            else
            {
                moveSpeed = defaultMoveSpeed;
            }

            if (!Mathf.Approximately(previousSpeed, moveSpeed))
            {
                OnSpeedChanged?.Invoke(moveSpeed);
            }
        }

        // Cette méthode sera appelée par le PlayerController (dans Update)
        public void Move(Vector2 input, bool sprint, bool jump)
        {
            inputMove = input;
            inputSprint = sprint;
            if (jump) jumpRequested = true;
        }

        private void ApplyMovement()
        {
            // Ne pas appliquer le mouvement normal si désactivé (pendant le dash)
            if (movementDisabled) return;

            // Calculer la direction de mouvement
            Vector3 desired = (transform.right * inputMove.x + transform.forward * inputMove.y);
            float desiredMag = desired.magnitude;
            if (desiredMag > 1f) desired /= desiredMag;

            CurrentSpeed = inputSprint ? sprintSpeed : moveSpeed;
            IsMoving = desired.sqrMagnitude > 0.01f;

            Vector3 horizontalVelocity = Vector3.zero;

            if (isGrounded)
            {
                // Réinitialiser le momentum au sol
                jumpMomentum = Vector3.zero;

                // Mouvement au sol
                if (desired.sqrMagnitude > 0f)
                {
                    horizontalVelocity = desired * CurrentSpeed;
                }

                // Saut
                if (jumpRequested)
                {
                    velocity.y = Mathf.Sqrt(jumpHeight * -2f * gravity);

                    // Capturer le momentum actuel pour le préserver en l'air
                    if (preserveJumpMomentum && desired.sqrMagnitude > 0f)
                    {
                        jumpMomentum = desired * CurrentSpeed * jumpMomentumMultiplier;
                    }

                    // Consommer le coyote time
                    coyoteTimeCounter = 0f;
                    jumpRequested = false;
                }
            }
            else
            {
                // Permettre le saut pendant le coyote time
                if (jumpRequested && coyoteTimeCounter > 0f)
                {
                    velocity.y = Mathf.Sqrt(jumpHeight * -2f * gravity);

                    // Capturer le momentum actuel pour le préserver en l'air
                    if (preserveJumpMomentum && desired.sqrMagnitude > 0f)
                    {
                        jumpMomentum = desired * CurrentSpeed * jumpMomentumMultiplier;
                    }

                    // Consommer le coyote time
                    coyoteTimeCounter = 0f;
                    jumpRequested = false;
                }

                // En l'air
                if (preserveJumpMomentum && jumpMomentum.sqrMagnitude > 0f)
                {
                    // Appliquer le momentum capturé au moment du saut
                    horizontalVelocity = jumpMomentum;

                    // Permettre un contrôle limité en l'air en PLUS du momentum
                    if (desired.sqrMagnitude > 0f)
                    {
                        horizontalVelocity += desired * CurrentSpeed * airControlFactor;
                    }
                }
                else
                {
                    // Mouvement aérien sans momentum préservé
                    horizontalVelocity = desired * CurrentSpeed * airControlFactor;
                }
            }

            // Reset jump request si pas utilisé
            jumpRequested = false;

            // Traiter le momentum externe
            ProcessExternalMomentum();
            horizontalVelocity += new Vector3(externalMomentum.x, 0, externalMomentum.z);

            // Appliquer la gravité seulement en l'air
            if (!isGrounded)
            {
                velocity.y += gravity * gravityMultiplier * Time.fixedDeltaTime;

                // Limiter la vitesse de chute
                if (velocity.y < maxFallSpeed)
                {
                    velocity.y = maxFallSpeed;
                }
            }

            // Ajouter le momentum vertical externe
            float verticalVelocity = velocity.y + externalMomentum.y;

            // Appliquer la vélocité au Rigidbody (les collisions seront gérées automatiquement)
            rb.linearVelocity = new Vector3(horizontalVelocity.x, verticalVelocity, horizontalVelocity.z);
        }

        private void HandleGroundCheck()
        {
            bool wasGrounded = isGrounded;

            // Créer un masque qui exclut le layer du joueur
            int playerLayer = gameObject.layer;
            int excludePlayerMask = ~(1 << playerLayer);

            if (groundCheck != null)
            {
                // Utiliser groundMask si défini, sinon détecter tout sauf le joueur
                if (groundMask != 0)
                {
                    isGrounded = Physics.CheckSphere(groundCheck.position, groundDistance, groundMask);
                }
                else
                {
                    // Détecter tous les colliders sauf le joueur et les triggers
                    isGrounded = Physics.CheckSphere(groundCheck.position, groundDistance, excludePlayerMask, QueryTriggerInteraction.Ignore);
                }
            }
            else
            {
                // Fallback: raycast vers le bas depuis le bas du collider
                float rayLength = groundDistance + 0.1f;
                Vector3 rayOrigin = transform.position + Vector3.up * 0.1f;

                if (groundMask != 0)
                {
                    isGrounded = Physics.Raycast(rayOrigin, Vector3.down, rayLength, groundMask);
                }
                else
                {
                    // Détecter tous les colliders sauf le joueur et les triggers
                    isGrounded = Physics.Raycast(rayOrigin, Vector3.down, rayLength, excludePlayerMask, QueryTriggerInteraction.Ignore);
                }
            }

            // Gérer le coyote time
            if (isGrounded)
            {
                coyoteTimeCounter = coyoteTime;

                // Réinitialiser la vélocité verticale au sol
                if (velocity.y < 0)
                {
                    velocity.y = 0f;
                }
            }
            else
            {
                coyoteTimeCounter -= Time.deltaTime;

                // Si on vient de quitter le sol naturellement (sans sauter), 
                // commencer avec une vélocité verticale nulle pour une chute progressive
                if (wasGrounded && velocity.y <= 0)
                {
                    velocity.y = 0f;
                }
            }
        }

        private void ProcessExternalMomentum()
        {
            if (externalMomentum.sqrMagnitude <= 1e-4f)
                return;

            if (externalMomentumGroundTimer > 0f)
                externalMomentumGroundTimer -= Time.fixedDeltaTime;

            if (isGrounded && externalMomentumGroundTimer <= 0f && externalMomentum.y > 0f)
                externalMomentum.y = 0f;

            float damping = externalMomentumDamping;
            if (isGrounded && externalMomentumGroundTimer <= 0f)
                damping *= 1.5f;

            if (damping > 0f)
            {
                externalMomentum = Vector3.MoveTowards(externalMomentum, Vector3.zero, damping * Time.fixedDeltaTime);
            }

            if (isGrounded && externalMomentumGroundTimer <= 0f && Mathf.Abs(externalMomentum.y) < 0.01f)
                externalMomentum.y = 0f;
        }

        /// <summary>
        /// Accès au Rigidbody pour les systèmes externes (Dash, etc.)
        /// </summary>
        public Rigidbody Rb => rb;
    }
}

using UnityEngine;

namespace FPS
{
    /// Contrôleur principal du joueur FPS 
    [RequireComponent(typeof(FPSInputHandler))]
    [RequireComponent(typeof(FPSMovement))]
    [RequireComponent(typeof(FPSMouseLook))]
    public class FPSPlayerController : MonoBehaviour
    {
        private FPSInputHandler inputHandler;
        private FPSMovement movement;
        private FPSMouseLook mouseLook;
        private FPSCameraEffects cameraEffects;

        private void Awake()
        {
            inputHandler = GetComponent<FPSInputHandler>();
            movement = GetComponent<FPSMovement>();
            mouseLook = GetComponent<FPSMouseLook>();

            if (mouseLook.CameraTransform != null)
            {
                cameraEffects = mouseLook.CameraTransform.GetComponent<FPSCameraEffects>();
                if (cameraEffects == null)
                {
                    cameraEffects = mouseLook.CameraTransform.gameObject.AddComponent<FPSCameraEffects>();
                }
            }

        }

        private void Update()
        {
            // Récupérer les inputs
            Vector2 moveInput = inputHandler.MoveInput;
            Vector2 lookInput = inputHandler.LookInput;
            bool jump = inputHandler.JumpPressed;
            bool sprint = inputHandler.SprintPressed;
            bool leanLeft = inputHandler.LeanLeftPressed;
            bool leanRight = inputHandler.LeanRightPressed;

            // Si le joueur est stun, neutraliser déplacement et actions mais laisser la caméra
            var stun = GetComponent<PlayerStunAutoFire>();
            if (stun != null && stun.IsStunned)
            {
                moveInput = Vector2.zero;
                jump = false;
                sprint = false;
                leanLeft = false;
                leanRight = false;
            }

            // Appliquer le mouvement
            movement.Move(moveInput, sprint, jump);

            // Consommer le jump après utilisation
            if (jump)
            {
                inputHandler.ConsumeJump();
            }

            mouseLook.Look(lookInput, moveInput, leanLeft, leanRight);

            if (cameraEffects != null)
            {
                cameraEffects.UpdateEffects(
                    movement.CurrentSpeed,
                    movement.IsGrounded,
                    sprint,
                    movement.IsMoving
                );
            }
        }

        // Propriétés publiques pour compatibilité avec les autres systèmes
        public Transform CameraTransform => mouseLook.CameraTransform;
        public CharacterController Controller => movement.Controller;
    }
}

