        private float slideSpeed = 12f;

        [SerializeField, Tooltip("Multiplicateur de la vitesse actuelle du joueur pendant le slide")]
        private float speedMultiplier = 1.3f;

        [SerializeField, Tooltip("Décélération progressive du slide")]
        private float slideDeceleration = 5f;

        [SerializeField, Tooltip("Vitesse minimale pour maintenir le slide")]
        private float minSlideSpeed = 3f;

        [SerializeField, Tooltip("Durée maximale du slide en secondes")]
        private float maxSlideDuration = 2f;

        [SerializeField, Tooltip("Cooldown entre chaque slide en secondes")]
        private float slideCooldown = 0.5f;

        [Header("Height Settings")]
        [SerializeField, Tooltip("Hauteur du CharacterController pendant le slide")]
        private float slideHeight = 1f;

        [SerializeField, Tooltip("Vitesse de transition de la hauteur")]
        private float heightTransitionSpeed = 10f;

        [Header("Camera Settings")]
        [SerializeField, Tooltip("Inclinaison de la caméra pendant le slide (en degrés)")]
        private float cameraTilt = 5f;

        [SerializeField, Tooltip("Vitesse de transition de l'inclinaison")]
        private float tiltTransitionSpeed = 8f;

        [Header("Momentum Settings")]
        [SerializeField, Tooltip("Conserver le momentum après le dash dans le slide")]
        private bool inheritDashMomentum = true;

        [SerializeField, Tooltip("Multiplicateur du momentum du dash")]
        private float dashMomentumMultiplier = 1.5f;

        // Références
        private CharacterController controller;
        private FPSMovement movement;
        private FPSMouseLook mouseLook;
        private Camera playerCamera;
        private PillarDashSystem dashSystem;

        // État du slide
        private bool isSliding;
        private float slideTimer;
        private float cooldownTimer;
        private Vector3 slideDirection;
        private float currentSlideSpeed;

        // État initial
        private float originalHeight;
        private Vector3 originalCenter;
        private float targetHeight;
        private float targetCenterY;
        private float targetTilt;

        public bool IsSliding => isSliding;

        private void Awake()
        {
            controller = GetComponent<CharacterController>();
            movement = GetComponent<FPSMovement>();
            mouseLook = GetComponent<FPSMouseLook>();
            dashSystem = GetComponent<PillarDashSystem>();

            if (controller != null)
            {
                originalHeight = controller.height;
                originalCenter = controller.center;
            }

            targetHeight = originalHeight;
            targetCenterY = originalCenter.y;
        }

        private void Start()
        {
            if (mouseLook != null && mouseLook.CameraTransform != null)
            {
                playerCamera = mouseLook.CameraTransform.GetComponent<Camera>();
            }
        }

        private void Update()
        {
            // Mise à jour du cooldown
            if (cooldownTimer > 0f)
            {
                cooldownTimer -= Time.deltaTime;
            }

            // Vérifier si le joueur est stun
            var stunComp = GetComponent<PlayerStunAutoFire>();
            bool isStunned = stunComp != null && stunComp.IsStunned;

            if (isSliding)
            {
                HandleSlide();
            }
            else
            {
                // Démarrer le slide avec Ctrl gauche
                bool slideInput = Input.GetKey(KeyCode.LeftControl);
                bool canSlide = movement.IsGrounded && cooldownTimer <= 0f && !isStunned;

                // Vérifier qu'on a une vitesse minimale ou qu'on bouge
                bool hasSpeed = movement.CurrentSpeed > minSlideSpeed || movement.IsMoving;

                if (slideInput && canSlide && hasSpeed)
                {
                    StartSlide();
                }
            }

            // Mise à jour de la hauteur et inclinaison
            UpdateHeight();
            UpdateCameraTilt();
        }

        private void StartSlide()
        {
            isSliding = true;
            slideTimer = 0f;

            // Déterminer la direction du slide
            Vector2 moveInput = GetComponent<FPSInputHandler>().MoveInput;

            if (moveInput.sqrMagnitude > 0.01f)
            {
                // Slide dans la direction du mouvement
                slideDirection = (transform.right * moveInput.x + transform.forward * moveInput.y).normalized;
            }
            else
            {
                // Slide dans la direction où regarde le joueur
                slideDirection = transform.forward;
            }

            // Calculer la vitesse initiale du slide
            currentSlideSpeed = slideSpeed;

            // Si on vient de dasher, hériter du momentum
            if (inheritDashMomentum && dashSystem != null && dashSystem.isDashing)
            {
                currentSlideSpeed = Mathf.Max(currentSlideSpeed, movement.CurrentSpeed * dashMomentumMultiplier);
            }
            else
            {
                // Sinon, multiplier la vitesse actuelle
                currentSlideSpeed = Mathf.Max(slideSpeed, movement.CurrentSpeed * speedMultiplier);
            }

            // Ajuster la hauteur du contrôleur
            targetHeight = slideHeight;
            targetCenterY = slideHeight / 2f;

            // Inclinaison de la caméra
            targetTilt = cameraTilt;
        }

        private void HandleSlide()
        {
            slideTimer += Time.deltaTime;

            // Vérifier les conditions d'arrêt
            bool slideInput = Input.GetKey(KeyCode.LeftControl);
            bool shouldStop = false;

            // Arrêter si on lâche la touche
            if (!slideInput)
            {
                shouldStop = true;
            }

            // Arrêter si on a dépassé la durée maximale
            if (slideTimer >= maxSlideDuration)
            {
                shouldStop = true;
            }

            // Arrêter si la vitesse est trop faible
            if (currentSlideSpeed < minSlideSpeed)
            {
                shouldStop = true;
            }

